package com.estoqueinteligente.report;
import java.math.BigDecimal;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import org.springframework.stereotype.Service;import com.estoqueinteligente.product.*;
@Service public class SmartSuggestionService{private static final BigDecimal MARGIN_FACTOR=new BigDecimal("1.30");private final ProductService products;public SmartSuggestionService(ProductService products){this.products=products;}public List<SmartSuggestionResponse> getSuggestions(){List<SmartSuggestionResponse> result=new ArrayList<>();LocalDate today=LocalDate.now();for(ProductResponse p:products.findAll()){if(p.getStatus()==ProductStatus.VENCIDO)result.add(suggestion(p,SuggestionType.VENCIDO,SuggestionPriority.ALTA,"Produto "+p.getName()+" está vencido. Sugestão: remover do estoque ou revisar imediatamente."));if(p.getStatus()==ProductStatus.VENCENDO){long days=ChronoUnit.DAYS.between(today,p.getExpirationDate());SuggestionPriority priority=days<=7?SuggestionPriority.ALTA:SuggestionPriority.MEDIA;result.add(suggestion(p,SuggestionType.VENCENDO,priority,"Produto "+p.getName()+" vence em "+days+" dias. Sugestão: criar promoção para evitar perda."));}if(p.getQuantity()<=p.getMinimumStock()){int buy=Math.max(1,p.getMinimumStock()-p.getQuantity());SuggestionPriority priority=p.getQuantity()==0?SuggestionPriority.ALTA:SuggestionPriority.MEDIA;result.add(suggestion(p,SuggestionType.ESTOQUE_BAIXO,priority,"Produto "+p.getName()+" está abaixo do estoque mínimo. Sugestão: comprar mais "+buy+" unidades."));}if(hasGoodMargin(p))result.add(suggestion(p,SuggestionType.BOA_MARGEM,SuggestionPriority.BAIXA,"Produto "+p.getName()+" possui boa margem de lucro. Sugestão: destacar em promoções."));}result.sort(Comparator.comparing(SmartSuggestionResponse::getPriority));return result;}private boolean hasGoodMargin(ProductResponse p){return p.getSalePrice().compareTo(p.getCostPrice())>0&&p.getSalePrice().compareTo(p.getCostPrice().multiply(MARGIN_FACTOR))>=0;}private SmartSuggestionResponse suggestion(ProductResponse p,SuggestionType type,SuggestionPriority priority,String message){return new SmartSuggestionResponse(type,priority,message,p.getId(),p.getName());}}
